create policy "medications_delete_prescribing_doctor" on public.prescription_medications for delete to authenticated using(exists(select 1 from public.prescriptions p where p.id=prescription_id and p.doctor_id=(select auth.uid())));
grant delete on public.prescription_medications to authenticated;
create or replace function public.update_prescription(prescription_uuid uuid,diagnosis_text text,notes_text text,medications jsonb) returns void language plpgsql security invoker set search_path=public,pg_temp as $$ declare item jsonb;begin if jsonb_typeof(medications)<>'array' or jsonb_array_length(medications)=0 then raise exception 'At least one medication is required';end if;if not exists(select 1 from public.prescriptions p where p.id=prescription_uuid and p.doctor_id=(select auth.uid())) then raise exception 'Only the prescribing doctor can edit this prescription';end if;update public.prescriptions set diagnosis=nullif(trim(diagnosis_text),''),clinical_notes=nullif(trim(notes_text),'') where id=prescription_uuid and doctor_id=(select auth.uid());delete from public.prescription_medications where prescription_id=prescription_uuid;for item in select * from jsonb_array_elements(medications) loop insert into public.prescription_medications(prescription_id,medicine_name,medicine_form,strength,dosage,frequency,duration,quantity,instructions) values(prescription_uuid,trim(item->>'medicine_name'),item->>'medicine_form',nullif(trim(item->>'strength'),''),trim(item->>'dosage'),trim(item->>'frequency'),trim(item->>'duration'),nullif(trim(item->>'quantity'),''),nullif(trim(item->>'instructions'),''));end loop;end $$;
revoke all on function public.update_prescription(uuid,text,text,jsonb) from public,anon; grant execute on function public.update_prescription(uuid,text,text,jsonb) to authenticated;
